def measure_churn(scrape,spawn,count):
    if type(count) is not int or not 1<=count<=32:raise ValueError('finite owned child count required')
    before=scrape();children=[]
    try:
        for _ in range(count):children.append(spawn())
        for child in children:child.wait(timeout=3)
        after=scrape()
        if after<before:raise ValueError('kernel counter reset; no interval delta')
        return {'before':before,'after':after,'delta':after-before,'owned_created':len(children),'owned_reaped':sum(child.returncode is not None for child in children)}
    finally:
        for child in children:
            if child.poll() is None:child.kill()
            child.wait(timeout=3)
