import math

def diagnose(text,nonblocking_random,tls_probe):
    def metric(name):
        rows=[line.split()[1] for line in text.splitlines() if line.startswith(name+' ')]
        if len(rows)!=1:raise ValueError('one entropy observation required')
        value=float(rows[0])
        if not math.isfinite(value) or value<0 or not value.is_integer():raise ValueError('finite nonnegative bit count')
        return int(value)
    available=metric('node_entropy_available_bits');pool=metric('node_entropy_pool_size_bits')
    if pool<=0 or available>pool:raise ValueError('invalid entropy pool observation')
    try:
        random_bytes=nonblocking_random()
        if not isinstance(random_bytes,bytes) or len(random_bytes)!=32:raise ValueError('32-byte sample required')
        random_state='ready'
    except BlockingIOError:random_state='would-block'
    except OSError:random_state='error'
    try:tls_state='ok' if tls_probe() is True else 'failed'
    except OSError:tls_state='failed'
    return {'available_bits':available,'pool_bits':pool,'random_nonblocking':random_state,'tls_probe':tls_state,'all_tls_blocked_proven':False}
